// Phase-2 twin cutover: re-POST the SAME rawtag payload to the CLOUD agent
// via cpack-ingest.staging:8447/v2/tags. Runs on a CLONED msg (2nd wire off
// normalize) so the PROD branch is untouched. Mutate+return (proven pattern).
const key = env.get("STAGING_TEE_INGEST_KEY") || "pk_cpack_af247745a1669a72bd82d70094a47d1588153422b03a4e6d";
const url = env.get("STAGING_TEE_URL") || "https://cpack-ingest.staging.packiot.app:8447/v2/tags";
if (!msg.payload || !Array.isArray(msg.payload.tags) || msg.payload.tags.length===0) return null;
msg.url = url;
msg.headers = { "Content-Type":"application/json", "X-Ingest-Key": key };
node.warn("__TEE__ key="+key.slice(0,10)+" tags="+msg.payload.tags.length);
return msg;
